// Guarda as mensagens de WhatsApp que o Kommo recebe/envia, por lead, para o Copiloto buscar.
// Os dados ficam na memória do próprio fluxo (static data) e são limpos após 3 dias.
const store = $getWorkflowStaticData('global');
store.leads = store.leads || {};
const body = $input.first().json.body || {};

// O Kommo envia formulário (application/x-www-form-urlencoded). Aceita o formato aninhado e o "achatado".
function lerMensagens(b) {
  if (b.message && b.message.add) return Object.values(b.message.add);
  const acc = {};
  for (const [k, v] of Object.entries(b)) {
    const m = k.match(/^message\[add\]\[(\d+)\]\[([^\]]+)\](?:\[([^\]]+)\])?$/);
    if (!m) continue;
    acc[m[1]] = acc[m[1]] || {};
    if (m[3]) { acc[m[1]][m[2]] = acc[m[1]][m[2]] || {}; acc[m[1]][m[2]][m[3]] = v; }
    else acc[m[1]][m[2]] = v;
  }
  return Object.values(acc);
}

const agora = Date.now();
for (const msg of lerMensagens(body)) {
  const lead = String(msg.entity_id || msg.element_id || '');
  if (!lead || !msg.text) continue;
  const ts = msg.created_at ? new Date(Number(msg.created_at) * 1000).toISOString() : new Date().toISOString();
  const autor = msg.type === 'outgoing' ? 'clinica' : 'cliente';
  const L = store.leads[lead] = store.leads[lead] || { atualizado: agora, mensagens: [] };
  if (!L.mensagens.some(x => x.id === msg.id)) {
    L.mensagens.push({ id: String(msg.id || (lead + '-' + ts)), texto: String(msg.text), autor, ts });
  }
  L.mensagens = L.mensagens.slice(-150);
  L.atualizado = agora;
}
for (const [k, L] of Object.entries(store.leads)) {
  if (agora - L.atualizado > 3 * 24 * 3600 * 1000) delete store.leads[k];
}
return [{ json: { ok: true } }];

// ================== CONFIGURE AQUI ==================
const TOKEN = 'TROQUE-POR-UMA-CHAVE-SECRETA'; // a mesma chave das Configurações do copiloto
// ====================================================
const q = $input.first().json.query || {};
if (q.token !== TOKEN) return [{ json: { ok: false, erro: 'Chave do copiloto inválida', mensagens: [] } }];
const store = $getWorkflowStaticData('global');
const L = (store.leads || {})[String(q.lead || '')];
const desde = q.desde || '1970-01-01T00:00:00.000Z';
const mensagens = L ? L.mensagens.filter(m => m.ts > desde) : [];
return [{ json: { ok: true, mensagens } }];
